quality={'scope':'23 targeted source-group boundary labels, not a random/held-out full-course dataset. Repeated growth record is control only. Some labels motivated safeguards; no general accuracy claim.','labels':labels,'schemes':{},'manual_mask_review':{'power_positive_frames':18,'power_total_frames':109,'visible_arm_missed_examples_ms':[310000,858000,1128000,1386000],'old_growth_false_positive_frames_ms':[1128000,1156000],'finding':'Power-series full body examples 1822000/1154000 detected, but some arm-only/pointer scenes missed. Old growth handwritten characters falsely masked as person. No comprehensive segmentation ground truth.'},'controlled':{'cases':len(controlled['cases']),'matched_expected':sum(x['decision_matches_expected'] for x in controlled['cases']),'failure':'Derivation erased and final-answer board remains unknown when compared directly; no image dropped.'}}
for scheme in ['baseline','no_mask_history','mask_adjacent','mask_history']:
 outcomes=[]
 for label in labels:
  row=rows[label['course']];a,b=label['source_pages'];merged=False if scheme=='baseline' else any(a in c['sourcePageIndices'] and b in c['sourcePageIndices'] for c in row['cases'][scheme]['collections'])
  outcomes.append(dict(label,predicted_same_page=merged,correct=merged==label['expected_same_page']))
 quality['schemes'][scheme]={'label_count':len(labels),'same_page_labels':sum(x['expected_same_page'] for x in labels),'different_page_labels':sum(not x['expected_same_page'] for x in labels),'same_page_confirmed':sum(x['expected_same_page'] and x['predicted_same_page'] for x in outcomes),'missed_same_page':sum(x['expected_same_page'] and not x['predicted_same_page'] for x in outcomes),'false_merges':sum(not x['expected_same_page'] and x['predicted_same_page'] for x in outcomes),'outcomes':outcomes}
