 samples=mask['courses'][row['course']];rd=statistics.median(x['read_resize_s'] for x in samples);infer=statistics.median(x['infer_transfer_mask_s'] for x in samples);wr=samples[0]['write_s'];row['mask_acquisition']={'read_resize_median_s':rd,'infer_transfer_mask_median_s':infer,'persist_once_s':wr}
 lines.append(f"|{row['label']}|{rd:.3f}|{infer:.3f}|{wr:.3f}|")
